# USUÁRIOS — persistência via GitHub API (fonte primária)
# ════════════════════════════════════════════════════════════════
_USERS_DEFAULT = {
    "ADMIN": {
        "senha_hash": None,  # preenchido abaixo após hash_senha estar definido
        "perfil": "gestor",
        "nome": "Administrador",
        "ultimo_acesso": None
    }
}

def _gh_secrets():
    """Retorna (token, repo, branch) dos secrets do Streamlit."""
    try:
        token  = st.secrets.get("GH_TOKEN","")
        repo   = st.secrets.get("GH_REPO","") or "denigrisadm/emplacamentovans"
        branch = st.secrets.get("GH_BRANCH","main")
        return token, repo, branch
    except Exception:
        return "", "denigrisadm/emplacamentovans", "main"

def _gh_get_file(api_url, token):
    """GET na API do GitHub. Retorna (conteúdo_bytes, sha) ou (None, '')."""
    import urllib.request
    try:
        req = urllib.request.Request(
            api_url,
            headers={"Authorization": f"token {token}",
                     "Accept": "application/vnd.github.v3+json"}
        )
        with urllib.request.urlopen(req, timeout=10) as r:
            data = json.loads(r.read().decode())
        content = base64.b64decode(data["content"].replace("\n",""))
        return content, data.get("sha","")
    except Exception:
        return None, ""

def _gh_put_file(api_url, token, branch, content_bytes, sha, message="update users.json"):
    """PUT na API do GitHub. Retorna True se ok."""
    import urllib.request
    try:
        payload = json.dumps({
            "message": message,
            "content": base64.b64encode(content_bytes).decode(),
            "sha": sha,
            "branch": branch
        }).encode()
        req = urllib.request.Request(
            api_url, data=payload, method="PUT",
            headers={"Authorization": f"token {token}",
                     "Content-Type": "application/json",
                     "Accept": "application/vnd.github.v3+json"}
        )
        with urllib.request.urlopen(req, timeout=15): pass
        return True
    except Exception:
        return False

def load_users():
    """Carrega usuários: 1º tenta GitHub, 2º arquivo local, 3º default."""
    token, repo, branch = _gh_secrets()

    # 1. Tentar GitHub (fonte primária — persiste entre reboots)
    if token and repo:
        api_url = f"https://api.github.com/repos/{repo}/contents/data/users.json"
        content, _err = _gh_get_file(api_url, token)
        if content:
            try:
                users = json.loads(content.decode("utf-8"))
                # Salva localmente como cache
                os.makedirs(DATA_DIR, exist_ok=True)
                with open(USERS_FILE,"w",encoding="utf-8") as f:
                    f.write(json.dumps(users, ensure_ascii=False, indent=2))
                return users
            except Exception:
                pass

    # 2. Arquivo local (cache ou deploy sem GitHub configurado)
    if os.path.exists(USERS_FILE):
        try:
            with open(USERS_FILE,"r",encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass

    # 3. Default mínimo
    return {
        "ADMIN": {
            "senha_hash": hash_senha("admin2025"),
            "perfil": "gestor",
            "nome": "Administrador",
            "ultimo_acesso": None
        }
    }

def save_users(users):
    """Salva usuarios: 1o GitHub (persistente), 2o arquivo local (cache).
    Retorna (gh_ok: bool, erro: str)."""
    os.makedirs(DATA_DIR, exist_ok=True)
    content_str = json.dumps(users, ensure_ascii=False, indent=2)
    content_bytes = content_str.encode("utf-8")
    gh_ok = False
    gh_err = "GitHub nao configurado"
    token, repo, branch = _gh_secrets()
    if token and repo:
        try:
            api_url = f"https://api.github.com/repos/{repo}/contents/data/users.json"
            _, sha_or_err = _gh_get_file(api_url, token)
            sha = sha_or_err if (sha_or_err and not str(sha_or_err).startswith("HTTP")) else ""
            resultado = _gh_put_file(api_url, token, branch, content_bytes, sha)
            # compatível com retorno bool OU tupla (bool, str)
            if isinstance(resultado, tuple):
                gh_ok, gh_err = resultado
            else:
                gh_ok = bool(resultado)
                gh_err = "" if gh_ok else "Falha no envio"
        except Exception as e:
            gh_ok = False
            gh_err = str(e)
    try:
        with open(USERS_FILE, "w", encoding="utf-8") as f:
            f.write(content_str)
    except Exception:
        pass
    return gh_ok, gh_err

def registrar_acesso(login):
    users = st.session_state.get("users_db", load_users())
    if login in users:
        try:
            agora_brt = datetime.datetime.utcnow() - datetime.timedelta(hours=3)
            users[login]["ultimo_acesso"] = agora_brt.strftime("%Y-%m-%dT%H:%M:%S")
            save_users(users)
            st.session_state.users_db = users
        except Exception:
            pass  # nunca travar o login por causa de persistência

