@st.cache_data(show_spinner=False)
def load_carteira(data_bytes):
    src = BytesIO(data_bytes)
    df = pd.read_excel(src)
    df.columns = [c.strip() for c in df.columns]
    df["CPF/CNPJ"]  = df["CPF/CNPJ"].astype(str).str.strip()
    df["CNPJ_NORM"] = df["CPF/CNPJ"].astype(str).str.replace(r"\D","",regex=True)
    df["VENDEDOR"]  = df.get("VENDEDOR", pd.Series(dtype=str)).astype(str).str.strip()
    df["VENDEDOR"]  = df["VENDEDOR"].str.title()
    if "Nome" in df.columns:
        df["Nome"] = df["Nome"].astype(str).str.strip()
    if "CEP" in df.columns:
        df["CEP_norm"] = df["CEP"].apply(norm_cep)
    return df

@st.cache_data(show_spinner=False)
def load_emplacamentos(data_bytes, label=""):
    src = BytesIO(data_bytes)
    raw = pd.read_excel(src, header=None, nrows=15)
    header_row = 0
    for i in range(len(raw)):
        if any("Chassi" in str(v) for v in raw.iloc[i].tolist()):
            header_row = i; break
    src.seek(0)
    df = pd.read_excel(src, header=header_row)
    df.columns = [str(c).strip() for c in df.columns]
    for col in ["CPFCNPJPROPRIETARIO","NOMEPROPRIETARIO","NO_CIDADE","NO_BAIRRO",
                "Placa","Chassi","Concessionário","Modelo","Marca","Segmento"]:
        if col in df.columns:
            df[col] = df[col].astype(str).str.strip()
    df["CNPJ_NORM"] = df["CPFCNPJPROPRIETARIO"].astype(str).str.replace(r"\D", "", regex=True)
    df["Data emplacamento"] = pd.to_datetime(df["Data emplacamento"], dayfirst=True, errors="coerce")
    if df["Data emplacamento"].isna().sum() > len(df) * 0.5:
        df["Data emplacamento"] = pd.to_datetime(df["Data emplacamento"], errors="coerce")
    df["Ano"] = df["Data emplacamento"].dt.year
    df["Mes"] = df["Data emplacamento"].dt.month
    df["Placa_norm"] = df["Placa"].str.replace("-","").str.replace(" ","").str.upper()
    df["NO_CIDADE_NORM"] = norm_str_series(df["NO_CIDADE"])
    df["NO_BAIRRO_NORM"] = norm_str_series(df["NO_BAIRRO"].fillna(""))
    if "NU_CEP" in df.columns:
        df["CEP_norm"] = (df["NU_CEP"].astype(str).str.replace(r"\D","",regex=True).str.zfill(8).str[:8])
    else:
        df["CEP_norm"] = ""
    df.dropna(subset=["Ano"], inplace=True)
    df["Ano"] = df["Ano"].astype(int)
    df["Mes"] = df["Mes"].astype(int)
    df["_fonte"] = label
    return df

@st.cache_data(show_spinner=False)
def merge_emp(data_bytes_list, labels):
    dfs = [load_emplacamentos(b, l) for b, l in zip(data_bytes_list, labels)]
    m = pd.concat(dfs, ignore_index=True)
    m.drop_duplicates(subset=["Chassi"], keep="last", inplace=True)
    m.sort_values("Data emplacamento", inplace=True)
    return m


def get_vendedores_ativos():
    """Retorna lista de nomes de vendedores cadastrados no sistema."""
    users = st.session_state.get("users_db", {})
    if not users: return []
    vendedores = [u["nome"] for u in users.values() if u.get("perfil") == "vendedor"]
    return sorted(list(set(vendedores)))

def get_consultor_distribuido(cnpj_norm, vendedores_ativos):
    """Distribui CNPJs de forma equilibrada e determinística entre os vendedores."""
    if not vendedores_ativos: return None
    h = int(hashlib.md5(cnpj_norm.encode()).hexdigest(), 16)
    idx = h % len(vendedores_ativos)
    return vendedores_ativos[idx]

def get_vendedor_final(cnpj_norm, cart_row, vendedores_ativos):
    if cart_row:
        v = safe_str(cart_row.get("VENDEDOR", ""), "").strip()
        if v and v != "—":
            return v
    return get_consultor_distribuido(cnpj_norm, vendedores_ativos)

def resolve_vendedor(cnpj, cart_cnpj_set, cart_map, vendedores_ativos):
    """
    Função central de atribuição — SEMPRE retorna (nome, na_carteira).
    Usar em TODOS os lugares do app para garantir consistência.
      - cart_cnpj_set : set de CNPJs presentes na carteira
      - cart_map      : dict CNPJ → nome do vendedor (da carteira)
      - vendedores_ativos : lista de vendedores ativos
    Retorna:
      (str nome_vendedor, bool na_carteira)
    """
    na_carteira = cnpj in cart_cnpj_set
    if na_carteira:
        v = cart_map.get(cnpj, "")
        nome = str(v).strip().title() if v and str(v).strip() not in ["", "—", "nan"] else "—"
    else:
        vd = get_consultor_distribuido(str(cnpj), vendedores_ativos)
        nome = vd.title() if vd else "—"
    return nome, na_carteira

def fmt_vendedor(nome, na_carteira):
    """Formata label do vendedor sempre mostrando status de cadastro."""
    if na_carteira:
        return nome
    return f"{nome} ⚠️ NÃO CADASTRADO"

def gerar_dashboard_gestao(df_g, df_cart, vendedores_ativos, periodo_label):
    """
    Gera relatório XLSX estilo dashboard por cliente para a página de Gestão.
    Cada CNPJ vira um bloco de linhas com até 5 emplacamentos detalhados.
    """
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side, GradientFill
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = "Dashboard Clientes"

    # ── Paletas ──
    PRETO    = "FF0A1628"
    BRANCO   = "FFFFFFFF"
    DOURADO  = "FFC8A84B"
    DOURADO_CL = "FFFFF3CC"
    VERDE    = "FF1E7E34"
    VERDE_CL = "FFD4EDDA"
    VERMELHO = "FFC0392B"
    ROSA_CL  = "FFFCE8E8"
    AZUL_CL  = "FFE8F0FF"
    CINZA_CL = "FFF5F5F5"
    CINZA_MED = "FFD0D0D0"
    LARANJA_CL = "FFFFF0E0"

    thin = Side(style="thin", color="FFCCCCCC")
    thick = Side(style="medium", color="FF888888")
    borda = Border(left=thin, right=thin, top=thin, bottom=thin)
    borda_thick = Border(left=thick, right=thick, top=thick, bottom=thick)

    def fill(hex_color):
        return PatternFill("solid", start_color=hex_color, end_color=hex_color)

    def font(bold=False, color=PRETO, size=10, italic=False):
        return Font(name="Calibri", bold=bold, color=color, size=size, italic=italic)

    def aln(h="left", v="center", wrap=False):
        return Alignment(horizontal=h, vertical=v, wrap_text=wrap)

    # ── Larguras de colunas ──
    col_widths = {
        "A": 6,   # #
        "B": 35,  # Empresa
        "C": 18,  # CNPJ
        "D": 22,  # Vendedor
        "E": 20,  # Cidade
        "F": 8,   # Total
        "G": 8,   # De Nigris
        "H": 8,   # Conc.
        "I": 10,  # % Nigris
        "J": 14,  # Status
        "K": 12,  # Data
        "L": 28,  # Modelo
        "M": 28,  # Concessionária
        "N": 16,  # Cidade Emplac.
    }
    for col, w in col_widths.items():
        ws.column_dimensions[col].width = w

    # ── CABEÇALHO GERAL (linhas 1-3) ──
    ws.row_dimensions[1].height = 32
    ws.row_dimensions[2].height = 18
    ws.row_dimensions[3].height = 20

    ws.merge_cells("A1:N1")
    c = ws["A1"]
    c.value = f"DASHBOARD DE GESTÃO — CLIENTES POR PERÍODO: {periodo_label.upper()}"
    c.font = Font(name="Calibri", bold=True, color=BRANCO, size=14)
    c.fill = fill(PRETO)
    c.alignment = aln("center", "center")
    c.border = borda

    ws.merge_cells("A2:N2")
    c = ws["A2"]
    c.value = f"Gerado em: {pd.Timestamp.now().strftime('%d/%m/%Y %H:%M')}  |  Total de clientes: {df_g['CNPJ_NORM'].nunique()}  |  Total de emplacamentos: {len(df_g)}"
    c.font = font(size=9, italic=True, color="FF555555")
    c.fill = fill(CINZA_CL)
    c.alignment = aln("center")

    # ── CABEÇALHO DE COLUNAS (linha 3) ──
    hdrs = ["#","Empresa","CNPJ","Vendedor","Cidade","Total","D.Nigris","Conc.","% Nigris","Status",
            "Data","Modelo","Concessionária","Cidade Emplac."]
    for ci, h in enumerate(hdrs, 1):
        cell = ws.cell(row=3, column=ci)
        cell.value = h
        cell.font = Font(name="Calibri", bold=True, color=BRANCO, size=10)
        cell.fill = fill(DOURADO)
        cell.alignment = aln("center", "center")
        cell.border = borda

    # ── Construir mapa vendedor por CNPJ ──
    cart_map = {}
    nc_set = set()
    if df_cart is not None:
        cart_map = df_cart.drop_duplicates("CNPJ_NORM").set_index("CNPJ_NORM")["VENDEDOR"].to_dict()
        nc_set = set(df_cart["CNPJ_NORM"].dropna().unique())

    n_vends = max(len(vendedores_ativos), 1)

    def get_vend_label(cnpj):
        v = cart_map.get(cnpj, "")
        if v and str(v).strip() and str(v).strip() not in ["—", "nan"]:
            return str(v).strip().title(), False  # (nome, is_nao_cadastrado)
        # Distribuição hash
        if vendedores_ativos:
            idx = int(hashlib.md5(str(cnpj).encode()).hexdigest(), 16) % n_vends
            return vendedores_ativos[idx].title(), True
        return "—", True

    # ── Agrupar por CNPJ ──
    grupos = []
    for cnpj, grp in df_g.groupby("CNPJ_NORM"):
        grp_sorted = grp.sort_values("Data emplacamento", ascending=False)
        ultimo = grp_sorted.iloc[0]
        total = len(grp)
        nigris = int(is_denigris(grp["Concessionário"]).sum())
        conc = total - nigris
        pct = round(nigris / total * 100, 0) if total else 0
        vend_nome, is_nc = get_vend_label(cnpj)
        grupos.append({
            "cnpj": cnpj,
            "nome": str(ultimo.get("NOMEPROPRIETARIO", "—")).strip(),
            "cnpj_fmt": str(ultimo.get("CPFCNPJPROPRIETARIO", cnpj)).strip(),
            "cidade": str(ultimo.get("NO_CIDADE", "—")).strip().title(),
            "vendedor": vend_nome,
            "is_nc": is_nc,
            "total": total,
            "nigris": nigris,
            "conc": conc,
            "pct": pct,
            "rows": grp_sorted.head(5).to_dict("records"),  # até 5 emplacamentos
        })

    # Ordenar: mais emplacamentos primeiro, depois por nome
    grupos.sort(key=lambda x: (-x["total"], x["nome"].upper()))

    # ── Escrever blocos ──
    cur_row = 4
    for idx, g in enumerate(grupos, 1):
        n_rows = max(len(g["rows"]), 1)
        bloco_start = cur_row
        bloco_end = cur_row + n_rows - 1

        # Cor do bloco de fundo
        if g["conc"] > 0 and g["nigris"] == 0:
            bg_resumo = ROSA_CL      # 100% concorrência
        elif g["nigris"] > 0 and g["conc"] == 0:
            bg_resumo = VERDE_CL     # 100% De Nigris
        elif g["is_nc"]:
            bg_resumo = LARANJA_CL  # Não cadastrado
        else:
            bg_resumo = AZUL_CL if idx % 2 == 0 else BRANCO

        # Altura das linhas do bloco
        for r in range(bloco_start, bloco_end + 1):
            ws.row_dimensions[r].height = 17

        # Linha separadora antes de cada bloco (exceto o primeiro)
        if idx > 1:
            for col in range(1, 15):
                cell = ws.cell(row=bloco_start - 1 if bloco_start > 4 else bloco_start, column=col)

        # ── Coluna A: número sequencial (span do bloco) ──
        if n_rows > 1:
            ws.merge_cells(f"A{bloco_start}:A{bloco_end}")
        c = ws.cell(row=bloco_start, column=1)
        c.value = idx
        c.font = Font(name="Calibri", bold=True, color=BRANCO, size=10)
        c.fill = fill(PRETO)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Coluna B: nome empresa (span) ──
        if n_rows > 1:
            ws.merge_cells(f"B{bloco_start}:B{bloco_end}")
        c = ws.cell(row=bloco_start, column=2)
        nc_tag = " ⚠ NÃO CADASTRADO" if g["is_nc"] else ""
        c.value = g["nome"] + nc_tag
        c.font = Font(name="Calibri", bold=True, color=PRETO if not g["is_nc"] else "FF994400", size=10)
        c.fill = fill(bg_resumo)
        c.alignment = aln("left", "center", wrap=True)
        c.border = borda

        # ── Coluna C: CNPJ (span) ──
        if n_rows > 1:
            ws.merge_cells(f"C{bloco_start}:C{bloco_end}")
        c = ws.cell(row=bloco_start, column=3)
        c.value = g["cnpj_fmt"]
        c.font = font(size=9, color="FF555555")
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Coluna D: vendedor (span) ──
        if n_rows > 1:
            ws.merge_cells(f"D{bloco_start}:D{bloco_end}")
        c = ws.cell(row=bloco_start, column=4)
        c.value = g["vendedor"]
        c.font = Font(name="Calibri", bold=False, color="FF0044AA" if not g["is_nc"] else "FF994400", size=9)
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center", wrap=True)
        c.border = borda

        # ── Coluna E: cidade (span) ──
        if n_rows > 1:
            ws.merge_cells(f"E{bloco_start}:E{bloco_end}")
        c = ws.cell(row=bloco_start, column=5)
        c.value = g["cidade"]
        c.font = font(size=9)
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Coluna F: total (span) ──
        if n_rows > 1:
            ws.merge_cells(f"F{bloco_start}:F{bloco_end}")
        c = ws.cell(row=bloco_start, column=6)
        c.value = g["total"]
        c.font = Font(name="Calibri", bold=True, size=11, color=PRETO)
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Coluna G: De Nigris (span) ──
        if n_rows > 1:
            ws.merge_cells(f"G{bloco_start}:G{bloco_end}")
        c = ws.cell(row=bloco_start, column=7)
        c.value = g["nigris"]
        c.font = Font(name="Calibri", bold=True, size=11, color="FF1E7E34" if g["nigris"] > 0 else "FFAAAAAA")
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Coluna H: Conc. (span) ──
        if n_rows > 1:
            ws.merge_cells(f"H{bloco_start}:H{bloco_end}")
        c = ws.cell(row=bloco_start, column=8)
        c.value = g["conc"]
        c.font = Font(name="Calibri", bold=True, size=11, color="FFC0392B" if g["conc"] > 0 else "FFAAAAAA")
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Coluna I: % Nigris (span) ──
        if n_rows > 1:
            ws.merge_cells(f"I{bloco_start}:I{bloco_end}")
        c = ws.cell(row=bloco_start, column=9)
        c.value = f"{int(g['pct'])}%"
        cor_pct = "FF1E7E34" if g["pct"] >= 50 else "FFC0392B"
        c.font = Font(name="Calibri", bold=True, size=10, color=cor_pct)
        c.fill = fill(bg_resumo)
        c.alignment = aln("center", "center")
        c.border = borda

        # ── Colunas J-N: até 5 emplacamentos detalhados (uma por linha) ──
        for ri, row_data in enumerate(g["rows"]):
            r = bloco_start + ri
            bg_row = VERDE_CL if is_denigris(pd.Series([row_data.get("Concessionário","")])).iloc[0] else ROSA_CL

            # J: Status
            is_dn_row = is_denigris(pd.Series([row_data.get("Concessionário","")])).iloc[0]
            status_txt = "✔ De Nigris" if is_dn_row else "✘ Concorrência"
            c = ws.cell(row=r, column=10)
            c.value = status_txt
            c.font = Font(name="Calibri", bold=True, size=9,
                         color="FF1E7E34" if is_dn_row else "FFC0392B")
            c.fill = fill(bg_row)
            c.alignment = aln("center", "center")
            c.border = borda

            # K: Data
            data_val = row_data.get("Data emplacamento")
            try:
                data_str = pd.Timestamp(data_val).strftime("%d/%m/%Y") if pd.notna(data_val) else "—"
            except:
                data_str = "—"
            c = ws.cell(row=r, column=11)
            c.value = data_str
            c.font = font(size=9)
            c.fill = fill(bg_row)
            c.alignment = aln("center", "center")
            c.border = borda

            # L: Modelo
            c = ws.cell(row=r, column=12)
            c.value = str(row_data.get("Modelo","—"))[:35]
            c.font = font(size=9)
            c.fill = fill(bg_row)
            c.alignment = aln("left", "center")
            c.border = borda

            # M: Concessionária
            c = ws.cell(row=r, column=13)
            c.value = str(row_data.get("Concessionário","—"))[:40]
            c.font = font(size=9)
            c.fill = fill(bg_row)
            c.alignment = aln("left", "center", wrap=True)
            c.border = borda

            # N: Cidade emplacamento
            c = ws.cell(row=r, column=14)
            c.value = str(row_data.get("NO_CIDADE","—")).title()
            c.font = font(size=9)
            c.fill = fill(bg_row)
            c.alignment = aln("center", "center")
            c.border = borda

        # Separador visual entre blocos
        cur_row = bloco_end + 1
        # Linha de separação cinza
        for col in range(1, 15):
            c_sep = ws.cell(row=cur_row, column=col)
            c_sep.fill = fill(CINZA_MED)
            c_sep.border = borda
        ws.row_dimensions[cur_row].height = 4
        cur_row += 1

    # ── Legenda no final ──
    cur_row += 1
    ws.merge_cells(f"A{cur_row}:N{cur_row}")
    c = ws.cell(row=cur_row, column=1)
    c.value = "LEGENDA:   🟩 Verde = 100% De Nigris   |   🟥 Rosa = 100% Concorrência   |   🟧 Laranja = Não Cadastrado   |   🔵 Azul = Misto"
    c.font = font(size=9, italic=True, color="FF555555")
    c.fill = fill(CINZA_CL)
    c.alignment = aln("left", "center")

    # ── Congelar painel ──
    ws.freeze_panes = "A4"

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    return buf


def gerar_relatorio_emplacamento(emp_mes, emp_area, cnpjs_carteira_set, todos_cnpjs_cart,
                                  sel_mes_lbl, sel_ano, consultor_nome):

    """Gera relatório XLSX estilizado igual ao modelo — cabeçalho colorido + tabela de dados."""
    from openpyxl import Workbook
    from openpyxl.styles import (Font, PatternFill, Alignment, Border, Side,
                                  GradientFill)
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = f"{sel_mes_lbl[:3]} {sel_ano}"

    # ── Paletas ──
    PRETO    = "FF1A1A1A"
    BRANCO   = "FFFFFFFF"
    VERDE    = "FF1E7E34"
    VERDE_CL = "FF28A745"
    VERMELHO = "FFC0392B"
    AZUL     = "FF1A3F6F"
    CINZA_CL = "FFF2F2F2"
    AMARELO  = "FFFFF2CC"
    ROSA_CL  = "FFFCE8E8"
    AZUL_CL  = "FFE8F0FF"

    thin = Side(style="thin", color="FFCCCCCC")
    borda_fina = Border(left=thin, right=thin, top=thin, bottom=thin)

    def fill(hex_color):
        return PatternFill("solid", start_color=hex_color, end_color=hex_color)

    def font(bold=False, color=BRANCO, size=11, italic=False):
        return Font(name="Arial", bold=bold, color=color, size=size, italic=italic)

    def aln(h="center", v="center", wrap=False):
        return Alignment(horizontal=h, vertical=v, wrap_text=wrap)

    # ── Colunas ──
    ws.column_dimensions["A"].width = 14   # Data
    ws.column_dimensions["B"].width = 22   # CNPJ
    ws.column_dimensions["C"].width = 40   # Cliente
    ws.column_dimensions["D"].width = 28   # Modelo
    ws.column_dimensions["E"].width = 22   # Chassi
    ws.column_dimensions["F"].width = 25   # Concessionária
    ws.column_dimensions["G"].width = 18   # Cidade

    # ════════════════════════════════════
    # LINHA 1 — Título principal
    # ════════════════════════════════════
    ws.merge_cells("A1:G1")
    ws.row_dimensions[1].height = 36
    c = ws["A1"]
    periodo = f"{sel_mes_lbl.upper()} DE {sel_ano}"
    c.value = f"EMPLACAMENTO ACUMULADO — {periodo}"
    c.font = Font(name="Arial", bold=True, color=BRANCO, size=14)
    c.fill = fill(PRETO)
    c.alignment = aln("center")

    # Consultor
    ws.merge_cells("A2:G2")
    ws.row_dimensions[2].height = 18
    c = ws["A2"]
    c.value = f"Consultor: {consultor_nome.title()}"
    c.font = Font(name="Arial", bold=False, color="FFAAAAAA", size=10, italic=True)
    c.fill = fill(PRETO)
    c.alignment = aln("center")

    # ════════════════════════════════════
    # LINHAS 3-4 — Cabeçalhos dos grupos
    # ════════════════════════════════════
    ws.row_dimensions[3].height = 30
    ws.row_dimensions[4].height = 26

    # Calcular grupos
    g1 = emp_mes[~emp_mes["CNPJ_NORM"].isin(todos_cnpjs_cart)]
    g2 = emp_mes[emp_mes["CNPJ_NORM"].isin(cnpjs_carteira_set) & ~is_denigris(emp_mes["Concessionário"])]
    g3 = emp_mes[is_denigris(emp_mes["Concessionário"])]
    total = len(emp_mes)

    def pct(n): return f"{round(n/total*100) if total else 0}%"

    # Col A: total emplacamentos (verde)
    ws["A3"].value = "EMPLACAMENTOS"
    ws["A3"].font = font(bold=True, color=BRANCO, size=10)
    ws["A3"].fill = fill(VERDE_CL)
    ws["A3"].alignment = aln()
    ws["A3"].border = borda_fina

    ws["A4"].value = total
    ws["A4"].font = font(bold=True, color=BRANCO, size=13)
    ws["A4"].fill = fill(VERDE_CL)
    ws["A4"].alignment = aln()
    ws["A4"].border = borda_fina

    # Linha com "100%"
    ws.row_dimensions[5].height = 20
    ws["A5"].value = "100%"
    ws["A5"].font = font(bold=True, color=BRANCO, size=11)
    ws["A5"].fill = fill(VERDE_CL)
    ws["A5"].alignment = aln()
    ws["A5"].border = borda_fina

    # Cols B-C: Não na carteira (preto)
    ws.merge_cells("B3:C3")
    ws.merge_cells("B4:C4")
    ws.merge_cells("B5:C5")
    ws["B3"].value = "EMPLACAMENTO DE VEÍCULOS QUE NÃO ESTÃO NA CARTEIRA"
    ws["B3"].font = font(bold=True, color=BRANCO, size=9)
    ws["B3"].fill = fill(PRETO)
    ws["B3"].alignment = aln("center", wrap=True)
    ws["B3"].border = borda_fina
    ws["B4"].value = len(g1)
    ws["B4"].font = font(bold=True, color=BRANCO, size=13)
    ws["B4"].fill = fill(PRETO)
    ws["B4"].alignment = aln()
    ws["B4"].border = borda_fina
    ws["B5"].value = pct(len(g1))
    ws["B5"].font = font(bold=True, color=BRANCO, size=11)
    ws["B5"].fill = fill(PRETO)
    ws["B5"].alignment = aln()
    ws["B5"].border = borda_fina

    # Cols D-E: Carteira + concorrência (vermelho)
    ws.merge_cells("D3:E3")
    ws.merge_cells("D4:E4")
    ws.merge_cells("D5:E5")
