def load_excel_from_github(filename):
    """Baixa arquivo do GitHub via API (suporta nomes com espaço). Retorna (BytesIO, erro_str)."""
    token, repo, branch = _gh_secrets()
    import urllib.request, urllib.parse

    if not repo:
        local_path = os.path.join("data", filename)
        if os.path.exists(local_path):
            try:
                with open(local_path, "rb") as f:
                    return BytesIO(f.read()), None
            except Exception as e:
                return None, f"Erro lendo local: {e}"
        return None, "Repo não configurado e arquivo local não encontrado"

    full_repo = repo if "/" in repo else f"denigrisadm/{repo}"
    filename_enc = urllib.parse.quote(filename)

    # Usa API do GitHub (funciona com espaços no nome, funciona em repos privados)
    api_url = f"https://api.github.com/repos/{full_repo}/contents/data/{filename_enc}?ref={branch}"
    try:
        req = urllib.request.Request(api_url)
        req.add_header("Accept", "application/vnd.github.v3.raw")
        if token:
            req.add_header("Authorization", f"token {token}")
        with urllib.request.urlopen(req, timeout=30) as r:
            return BytesIO(r.read()), None
    except Exception as e:
        # Fallback: tenta URL raw mesmo assim
        try:
            url_raw = f"https://raw.githubusercontent.com/{full_repo}/{branch}/data/{filename_enc}"
            req2 = urllib.request.Request(url_raw)
            if token:
                req2.add_header("Authorization", f"token {token}")
            with urllib.request.urlopen(req2, timeout=30) as r2:
                return BytesIO(r2.read()), None
        except Exception as e2:
            local_path = os.path.join("data", filename)
            if os.path.exists(local_path):
                try:
                    with open(local_path, "rb") as f:
                        return BytesIO(f.read()), None
                except: pass
            return None, f"API: {e} | RAW: {e2}"

def carregar_dados_se_necessario():
    """Coordena o carregamento dos dados usando os loaders específicos."""
    if st.session_state.user is None:
        return
    # Se já carregou com sucesso, não recarrega
    if st.session_state.get("dados_carregados"):
        return
    token, repo, _ = _gh_secrets()

    # 1. AREA (Removida conforme solicitação)
    st.session_state.df_area = None
    
    # 2. CARTEIRA
    if st.session_state.df_cart is None:
        src = None
        for filename in ["CARTEIRA_VANS.xlsx", "CARTEIRA.xlsx"]:
            src, err = load_excel_from_github(filename)
            if src:
                st.session_state["_cart_erro"] = None
                break
            else:
                st.session_state["_cart_erro"] = f"{filename}: {err}"
        if src:
            st.session_state.df_cart = load_carteira(src.read())

    # 3. EMPLACAMENTOS — armazena bytes para cache funcionar
    if not st.session_state.get("_emp_bytes_list"):
        arquivos_emp = ["EMPLACAMENTO APP VANS.xlsx"]
        bytes_list, labels_list, emp_erros = [], [], []
        for arq in arquivos_emp:
            src, err = load_excel_from_github(arq)
            if src:
                bytes_list.append(src.read())
                labels_list.append(arq)
            else:
                emp_erros.append(f"{arq}: {err}")
        st.session_state["_emp_bytes_list"] = bytes_list
        st.session_state["_emp_labels_list"] = labels_list
        st.session_state["_emp_erros"] = emp_erros if not bytes_list else []
        if bytes_list:
            # merge_emp cacheado — só roda uma vez enquanto bytes não mudarem
            st.session_state["_df_emp_merged"] = merge_emp(bytes_list, labels_list)
            st.session_state.df_emp_list = [True]  # sinaliza que carregou

    # Marca como carregado
    if st.session_state.df_cart is not None or st.session_state.get("_df_emp_merged") is not None:
        st.session_state.dados_carregados = True

