    # Q1: Clientes da CARTEIRA que compraram na concorrência no mês
    if len(cnpjs_carteira_set) > 0:
        q1_df = emp_mes[
            emp_mes["CNPJ_NORM"].isin(cnpjs_carteira_set) &
            ~is_denigris(emp_mes["Concessionário"])
        ].copy()
    else:
        q1_df = pd.DataFrame()

    # Q2: Emplacamentos de clientes NÃO CADASTRADOS (Oportunidades)
    # Já estão filtrados para o vendedor atual pela lógica de atribuição dinâmica acima
    q2_df = emp_mes[~emp_mes["CNPJ_NORM"].isin(todos_cnpjs_cart)].copy()
    if not q2_df.empty:
        q2_df["Vendedor_Atribuido"] = q2_df["VENDEDOR_ATRIBUIDO"]


    # Q3: Compraram na Comercial De Nigris (no mês, área + carteira)
    q3_df = emp_mes[is_denigris(emp_mes["Concessionário"])].copy()

    # Q4: Top 3 do período selecionado (mês/ano filtrado)
    top_hist = emp_mes.groupby(["CNPJ_NORM","NOMEPROPRIETARIO","NO_CIDADE"]).agg(
        Total=("Chassi","count"),
        Nigris=("Concessionário", lambda x: is_denigris(x).sum()),
    ).reset_index().sort_values("Total", ascending=False).head(3).reset_index(drop=True)

    # Preparar mapa resolve_vendedor para uso nos quadrantes
    _cart_cnpjs_emp = set(df_cart["CNPJ_NORM"].dropna().unique()) if df_cart is not None else set()
    _cart_map_emp   = df_cart.drop_duplicates("CNPJ_NORM").set_index("CNPJ_NORM")["VENDEDOR"].to_dict() if df_cart is not None else {}
    _vends_emp      = get_vendedores_ativos()

    # Cards dos quadrantes
